ame":"shell","arguments":{"command":"python3 << 'EOF'\n# Verify data one more time\n\n# Check that we have FY 2024 actual data from 2025 bulletin\nimport json\n\ndata = json.load(open('/app/resources/treasury_bulletin_2025_09.json'))\nelem = data['document']['elements'][156]\ncontent = elem['content']\n\n# Find FY 2024 row (not estimates)\nimport re\n# Look for the row with just \"2024\" not \"2024 - Est\"\nrows = re.findall(r'<tr><td>(\\d{4}(?:\\s*-\\s*Est)?)</td><td>([0-9,]+)</td>', content)\nprint(\"FY 2024 data from 2025 bulletin:\")\nfor row in rows:\n    print(f\"  {row[0]}: {row[1]}\")\n\n# Also verify FY 2023 data is correct  \ndata = json.load(open('/app/resources/treasury_bulletin_2024_09.json'))\nelem = data['document']['elements'][185]\ncontent = elem['content']\n\nrows = re.findall(r'<tr><td>(\\d{4}(?:\\s*-\\s*Est)?)</td><td>([0-9,]+)</td>', content)\nprint(\"\\nFY 2023 data from 2024 bulletin:\")\nfor row in rows[:6]:\n    print(f\"  {row[0]}: {row[1]}\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
